# Generates ~/.gitconfig
set -e -u -o pipefail
mkdir -p -m 0555 ~/.dotfiles/.empty
cat <<EOF
# Autogenerated by ~/.dotfiles/gitconfig.sh

[user]
	name = Ivan Krasilnikov
	email = $(echo -e "\\x69\\x76\\x61\\x6e\\x6b\\x40\\x69\\x76\\x61\\x6e\\x6b\\x2e\\x6d\\x65")

[alias]
	amend = commit --amend
	br = branch
	ci = commit
	cia = commit --amend
	caa = commit -a --amend
	co = checkout
	cp = cherry-pick
	detach = !git checkout HEAD^0
	diffh = diff HEAD
	g = !gitg
	lg = log --pretty=oneline --abbrev-commit --decorate
	pp = !git pull && git push
	rbc = rebase --continue
	root = rev-parse --show-toplevel
	st = status
	unstage = reset HEAD --
	# git gc with pruning; add --aggressive for more effect
	gca = !git -c gc.reflogExpire=0 -c gc.reflogExpireUnreachable=0 -c gc.rerereresolved=0 -c gc.rerereunresolved=0 -c gc.pruneExpire=now gc --prune=now

[color]
	ui = auto

[core]
	pager = less -FSRXi

[init]
	# Point to an empty directory to avoid copying sample hooks to every repo
	# Look for sample hooks in /usr/share/git-core/templates/hooks/
	templateDir = $HOME/.dotfiles/.empty/

[pull]
	ff = only
	rebase = false

[push]
	default = matching

[url "git@github.com:"]
	pushInsteadOf = "git://github.com/"
	pushInsteadOf = "https://github.com/"

[url "git@gist.github.com:"]
	pushInsteadOf = "git://gist.github.com/"
EOF
